package com.carpidi.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity public class StyleQuestionnaire { @Id @GeneratedValue private UUID id; @ManyToOne(optional=false) private User customer; private String bodyType; private String skinTone; private String heightRange; private String stylePreferences; private boolean consent; private Instant createdAt=Instant.now(); protected StyleQuestionnaire(){} public StyleQuestionnaire(User customer,String bodyType,String skinTone,String heightRange,String stylePreferences,boolean consent){this.customer=customer;this.bodyType=bodyType;this.skinTone=skinTone;this.heightRange=heightRange;this.stylePreferences=stylePreferences;this.consent=consent;} public UUID getId(){return id;} public String getBodyType(){return bodyType;} public String getSkinTone(){return skinTone;} public String getHeightRange(){return heightRange;} public String getStylePreferences(){return stylePreferences;} }
